package org.freecad.mobilelab;
import org.json.*;import java.io.*;import java.nio.file.*;
public final class JewelleryRegression {
    interface Action{void run()throws Exception;}static int checks;
    static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
    static void near(double a,double b,double tolerance){check(Math.abs(a-b)<tolerance,"Expected "+b+", got "+a);}
    static void reject(Action a)throws Exception{try{a.run();}catch(Exception e){checks++;return;}throw new AssertionError("Invalid input accepted");}
    static JSONObject object(int id)throws Exception{JSONArray a=new JSONArray(NativeCad.objects());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==id)return a.getJSONObject(i);throw new AssertionError("Missing object");}
    static JSONObject report(int id)throws Exception{return new JSONObject(NativeCad.analyze(id,3));}
    public static void main(String[] args)throws Exception{
        NativeCad.clear();ProjectStore.reset();for(String type:JewelleryCatalog.LABELS.keySet()){int id=NativeCad.create(type,JewelleryCatalog.DEFAULTS.get(type));JSONObject a=report(id);check(a.getBoolean("validCAD"),"Invalid "+type);check(a.getInt("solids")==1,"Disconnected "+type);check(object(id).getDouble("volume")>0,"No volume "+type);check(new MeshFrame(NativeCad.meshAtDetail(id,50000),NativeCad.lines(id)).count>0,"Invisible "+type);}
        int oval=NativeCad.create("Oval bezel",new double[]{8,6,.6,3,1});near(object(oval).getDouble("volume"),Math.PI/4*((9.2*7.2-7.4*5.4)*2+(9.2*7.2-8*6)),.0001);
        String before=NativeCad.objects();reject(()->NativeCad.create("Cushion bezel",new double[]{8,6,.6,3,1,3}));reject(()->NativeCad.create("Oval prongs",new double[]{8,6,.6,4,2,3.5,.9}));reject(()->NativeCad.create("Comfort ring",new double[]{18,1.6,3,1.6}));check(before.equals(NativeCad.objects()),"Invalid template changed scene");
        int text=NativeCad.textSolid(new double[]{0,0,4,0,4,4,0,4,1,1,3,1,3,3,1,3},new int[]{4,4},2);near(object(text).getDouble("volume"),24,.00001);check(report(text).getBoolean("validCAD"),"Text hole invalid");reject(()->NativeCad.textSolid(new double[]{0,0,1,1},new int[]{4},2));reject(()->NativeCad.textSolid(new double[]{0,0,4,0,4,4,0,4},new int[]{4},0));
        int source=NativeCad.create("Box",new double[]{2,2,2}),rail=NativeCad.curve("Polyline",new double[]{0,0,0,1,20,0,0,1},false,0),array=NativeCad.arrayCurve(source,rail,4,false);near(object(array).getDouble("volume"),32,.00001);near(object(array).getJSONArray("bounds").getDouble(0),22,.00001);check(report(array).getInt("solids")==4,"Wrong curve copy count");int closed=NativeCad.create("Circle",new double[]{10}),loop=NativeCad.arrayCurve(source,closed,4,true);near(object(loop).getDouble("volume"),32,.00001);near(object(loop).getJSONArray("bounds").getDouble(0),22,.0001);reject(()->NativeCad.arrayCurve(source,rail,101,false));
        near(JewelleryCatalog.mass(1000,10.5),10.5,.0000001);reject(()->JewelleryCatalog.mass(0,10));reject(()->JewelleryCatalog.mass(1000,Double.NaN));
        int ring=NativeCad.create("Ring",new double[]{18,1.6,3}),cast=NativeCad.duplicate(ring,0,0,0);JSONArray bounds=object(ring).getJSONArray("bounds");NativeCad.scale(cast,1/.98);NativeCad.visible(ring,false);ProjectStore.castingRecords.put(new JSONObject().put("source",ring).put("output",cast).put("percent",2).put("originalBounds",bounds));near(object(ring).getJSONArray("dims").getDouble(0),18,.000001);near(object(cast).getJSONArray("dims").getDouble(0),18/.98,.000001);
        File root=Files.createTempDirectory("jewellery-").toFile(),cache=new File(root,"cache");cache.mkdir();try{JSONArray expected=new JSONArray(NativeCad.objects());File f=new File(root,"all.fcml");ProjectStore.save(f,cache);NativeCad.beginTransaction(true);try{ProjectStore.restore(f,cache);NativeCad.setWorkspace(ProjectStore.workspace());NativeCad.commitTransaction();}catch(Throwable t){NativeCad.rollbackTransaction();throw t;}JSONArray actual=new JSONArray(NativeCad.objects());check(actual.length()==expected.length(),"New templates lost on reopen");for(int i=0;i<expected.length();i++){near(actual.getJSONObject(i).getDouble("volume"),expected.getJSONObject(i).getDouble("volume"),.001);for(int j=0;j<3;j++)near(actual.getJSONObject(i).getJSONArray("bounds").getDouble(j),expected.getJSONObject(i).getJSONArray("bounds").getDouble(j),.001);}check(ProjectStore.castingRecords.length()==1,"Casting allowance record lost");JSONObject c=ProjectStore.castingRecords.getJSONObject(0);near(object(c.getInt("source")).getJSONArray("dims").getDouble(0),18,.000001);near(object(c.getInt("output")).getJSONArray("dims").getDouble(0),18/.98,.000001);File stl=new File(root,"setting.stl");NativeCad.writeWithTolerance(stl.toString(),"stl",actual.getJSONObject(0).getInt("id"),.015);check(stl.length()>84,"Template STL empty");check(cache.list().length==0,"Temporary files leaked");}finally{ArchiveIO.deleteTree(root);}
        System.out.println("PASS: "+checks+" jewellery assertions: eight exact templates, connected settings, text holes, equal-length curve arrays, mass units, casting originals/records, project/STL persistence");
    }
}
